#[derive(Clone, Copy, Debug)]
enum IceBossBroadStep {
    Start,
    OnStop,
    OnStart,
    OnTimer2000,
    OnTimer8000,
    OnTimer10000,
    OnTimer13000,
    OnTimer16000,
    OnTimer19000,
    OnTimer21000,
}

fn ice_boss_broad_run(ctx: &Ctx, mut step: IceBossBroadStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            IceBossBroadStep::Start => {
                step = IceBossBroadStep::OnStop;
                continue 'machine;
            }
            IceBossBroadStep::OnStop => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnStart => {
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnTimer2000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("ice_dun03"),
                        Val::from("Someone has put out Thor's flames... Infidel!"),
                        ctx.constant("BC_MAP")?,
                        Val::from(16737843),
                    ],
                )?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnTimer8000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("ice_dun03"),
                        Val::from("I, Ktullanux, must protect and preserve Thor's fierce flames..."),
                        ctx.constant("BC_MAP")?,
                        Val::from(16737843),
                    ],
                )?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnTimer10000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("ice_dun03"),
                        Val::from("As the master of this cave, I vow vengeance!"),
                        ctx.constant("BC_MAP")?,
                        Val::from(16737843),
                    ],
                )?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnTimer13000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("ice_dun03"),
                        Val::from("Only a human would be so foolhardy...."),
                        ctx.constant("BC_MAP")?,
                        Val::from(16737843),
                    ],
                )?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnTimer16000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("ice_dun03"),
                        Val::from("Your curiosity will cost you, human."),
                        ctx.constant("BC_MAP")?,
                        Val::from(16737843),
                    ],
                )?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnTimer19000 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("ice_dun03"),
                        Val::from("Prepare yourself for a freezing realm of pain which you cannot possibly imagine!"),
                        ctx.constant("BC_MAP")?,
                        Val::from(16737843),
                    ],
                )?;
                return Err(Stop::End);
            }
            IceBossBroadStep::OnTimer21000 => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                ctx.call(Function::DoNpcEvent, vec![Val::from("ice_boss#on::OnStart")])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn ice_boss_broad(ctx: &Ctx) -> Script {
    ice_boss_broad_run(ctx, IceBossBroadStep::Start, Vec::new()).map(|_| ())
}

